#include <iostream>
#include <iomanip>

int main() {
    int num;
    if (!(std::cin >> num) || num == 0) {
        std::cout << "No numbers entered." << std::endl;
        return 0;
    }

    int maxVal = num;
    int count = 1;

    while (std::cin >> num && num != 0) {
        if (num > maxVal) {
            maxVal = num;
            count = 1;
        } else if (num == maxVal) {
            ++count;
        }
    }

    std::cout << "The largest number is " << maxVal << std::endl;
    std::cout << "The occurrence count of the largest number is " << count << std::endl;

    return 0;
}

#include <iostream>
#include <string>

int main() {
    std::string s1, s2;
    if (!std::getline(std::cin, s1) || !std::getline(std::cin, s2)) {
        return 0;
    }

    size_t i = 0;
    while (i < s1.length() && i < s2.length() && s1[i] == s2[i]) {
        ++i;
    }

    if (i == 0) {
        std::cout << s1 << " and " << s2 << " have no common prefix" << std::endl;
    } else {
        std::cout << "The common prefix is " << s1.substr(0, i) << std::endl;
    }

    return 0;
}

#include <iostream>
#include <cstdint>

int main() {
    short num;
    if (std::cin >> num) {
        std::cout << "Enter an integer: " << num << std::endl;
        std::cout << "The bits are ";
        uint16_t uval = static_cast<uint16_t>(num);
        for (int i = 15; i >= 0; --i) {
            int bit = (uval >> i) & 1;
            std::cout << bit;
        }
        std::cout << std::endl;
    }
    return 0;
}
